import {VERDANTYR_ID} from './paladin-data.js?v=0.87.0';
export function paladinEncounterRoute(route){if(!route||route.paladinExpanded||route.room!=='verdantJungle')return route;return {...route,paladinExpanded:true,tables:route.tables.map(t=>{const slots=t.slots.map(s=>({...s})),donor=slots.filter(s=>s.weight>2).sort((a,b)=>b.weight-a.weight)[0];if(!donor)throw Error('Missing jungle encounter budget');donor.weight-=2;return {...t,slots:[...slots,{species_id:VERDANTYR_ID,min_level:16,max_level:20,weight:2,rarity:'Rare',authoredSlot:true,approvedPaladin:true}]};})};}
export function jungleRoute(room){return room==='verdantJungle'?{room,area:{id:'VERDANT-JUNGLE',rate:'NORMAL'},tables:['DAY','NIGHT'].map(phase=>({id:room+'-'+phase,phase,slots:[{species_id:'042',min_level:16,max_level:19,weight:45,authoredSlot:true},{species_id:'139',min_level:16,max_level:19,weight:35,authoredSlot:true},{species_id:'295',min_level:17,max_level:20,weight:20,authoredSlot:true}]}))}:null;}
export function installJungleWorld(maps){const m=maps.orchardCanopy;m.sidePaths??=[];m.sidePaths.push({gateId:'verdant-jungle-entry',points:[[23,17],[23,5]]});m.gates.push({id:'verdant-jungle-entry',label:'Verdant Understory · rare jungle guardians',x:23,y:5,to:'verdantJungle',arrival:[3,17,'right'],door:true});maps.verdantJungle={name:'Verdant Understory',area:'VERDANT-JUNGLE',terrain:'court-jungle',bloom:false,road:[[1,17],[10,17],[10,8],[25,8],[25,23],[39,23],[39,14]],grass:[[5,20,18,28],[14,4,22,13],[27,5,42,16],[28,20,43,28]],sidePaths:[{points:[[10,17],[20,17],[20,23],[25,23]]}],props:[],spots:[{id:'verdant-jungle-lore',label:'A scarred tree',x:39,y:14},{id:'area-sign',label:'Jungle noticeboard',x:5,y:18,routeSign:true}],gates:[{id:'verdant-jungle-back',label:'Return to Orchard Canopy',x:1,y:17,to:'orchardCanopy',arrival:[23,7,'down'],door:true}]};}
